import type { RequestHandler } from 'express';

const buckets = new Map<string, { tokens: number; ts: number }>();
const CAP = 60;
const REFILL_PER_MS = CAP / 60_000;

export const rateLimit: RequestHandler = (req, res, next) => {
  const key = req.ip ?? 'unknown';
  const now = Date.now();
  const b = buckets.get(key) ?? { tokens: CAP, ts: now };
  b.tokens = Math.min(CAP, b.tokens + (now - b.ts) * REFILL_PER_MS);
  b.ts = now;
  if (b.tokens < 1) return res.status(429).json({ error: 'rate limited' });
  b.tokens -= 1;
  buckets.set(key, b);
  next();
};
